function validate([nums, lower, upper]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => v < -2147483648 || v > 2147483647)) return 'Each value fits in a 32-bit signed integer.';
  if (lower < -100000 || upper > 100000) return 'lower and upper are between -100000 and 100000.';
  if (lower > upper) return 'lower must not exceed upper.';
  return null;
}

