function countRangeSum(nums, lower, upper) {
  const prefix = [0];
  for (const num of nums) {
    prefix.push(prefix[prefix.length - 1] + num);
  }
  const merged = new Array(prefix.length);

  function sortAndCount(lo, hi) {
    if (hi - lo <= 1) return 0;
    const mid = (lo + hi) >> 1;
    let count = sortAndCount(lo, mid) + sortAndCount(mid, hi);
    let low = mid;
    let high = mid;
    for (let i = lo; i < mid; i++) {
      while (low < hi && prefix[low] - prefix[i] < lower) low++;
      while (high < hi && prefix[high] - prefix[i] <= upper) high++;
      count += high - low;
    }
    let left = lo;
    let right = mid;
    for (let k = lo; k < hi; k++) {
      if (right >= hi || (left < mid && prefix[left] <= prefix[right])) {
        merged[k] = prefix[left++];
      } else {
        merged[k] = prefix[right++];
      }
    }
    for (let k = lo; k < hi; k++) prefix[k] = merged[k];
    return count;
  }

  return sortAndCount(0, prefix.length);
}

