function countRangeSum(nums, lower, upper) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let sum = 0;
    for (let j = i; j < nums.length; j++) {
      sum += nums[j];
      if (sum >= lower && sum <= upper) total++;
    }
  }
  return total;
}

